pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with some Ether
        vm.deal(address(c), 1 ether);
        // Non-owner tries to call sendTo
        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 0);
        vm.prank(nonOwner);
        bool ok;
        try c.sendTo(nonOwner, 0.5 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference reverts for non-owner, so ok should be false.
        // The buggy version does not revert, so ok is true; assertTrue(false) fails on the buggy version.
        assertTrue(!ok);
    }
}

