pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address payable receiver = payable(address(0x1234));
        uint amount = 100;
        // Fund contract so transfer doesn't revert
        vm.deal(address(c), amount);
        vm.prank(address(this)); // owner is deployer (address(this) in setUp? Actually msg.sender in constructor is test contract address, but we need to use actual owner)
        // Actually the owner is the address that deployed C; in setUp(), c = new C() where msg.sender is the test contract address.
        // So we prank as the test contract's own address.
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        // Reference: receiver.balance == 100. Mutant: receiver.balance == 0.
        assertTrue(receiver.balance == 100);
    }
}

