pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address payable receiver = payable(address(0x1234));
        vm.deal(address(c), 10000);  // give owner some ether
        assertEq(address(c).balance, 10000);
        uint amount = 1234;
        // owner calls sendTo
        vm.prank(address(this));  // constructor set msg.sender as owner
        c.sendTo(receiver, amount);
        // reference: receiver.balance == 1234; mutant: receiver.balance == 0
        assertTrue(receiver.balance == amount);
    }
}
